/// one test, with no pointer to follow, rejects Cyrillic, Greek, Hebrew, CJK and
/// emoji outright.
pub(super) static BLOCKS: [u64; 4] = [
    0x0000101260000007,
    0x0000000000000000,
    0x0000008000000000,
    0x8000000000000000,
];

